        ["Moodles_Panic_desc_lvl1"] = "-1.3%暴击率,无聊效果被移除并暂时免疫",
        ["Moodles_Panic_desc_lvl2"] = "-2.6%暴击率,-0.1x近战伤害倍率,起身速度加快",
        ["Moodles_Panic_desc_lvl3"] = "-3.9%暴击率,-0.2x近战伤害倍率,-0.19x枪械伤害倍率,起身速度加快",
        ["Moodles_Panic_desc_lvl4"] = "-5.2%暴击率,-0.3x近战伤害倍率,-0.25x枪械伤害倍率,起身速度加快",
        ["Moodles_Sick_desc_lvl1"] = "体温略微升高,若被感染则生命值缓慢流失",
        ["Moodles_Sick_desc_lvl2"] = "负重-1,体温略微升高,愈合速度减慢",
        ["Moodles_Sick_desc_lvl3"] = "负重-2,体温升高,愈合速度大幅减慢,若被感染或中毒则生命值严重受损",
        ["Moodles_Sick_desc_lvl4"] = "负重-3,体温严重升高,生命值缓慢下降,若被感染或中毒则生命值降至危险状态",
        ["Moodles_Stress_desc_lvl1"] = "紧张不安, 抽根烟, 看本书, 看会电视, 放松一下",
        ["Moodles_Stress_desc_lvl2"] = "-10%近战与远程伤害,不快乐感缓慢上升,搜索范围减小",
        ["Moodles_Stress_desc_lvl3"] = "-20%战与远程伤害,不快乐感快速上升,搜索范围中等减小",
        ["Moodles_Stress_desc_lvl4"] = "-30%战与远程伤害,不快乐感急速上升,-95%搜索效率",
        ["Moodles_Thirst_desc_lvl1"] = "口干舌燥, 需要喝点水",
        ["Moodles_Thirst_desc_lvl2"] = "负重-1,体温略微升高",
        ["Moodles_Thirst_desc_lvl3"] = "负重-2,体温升高",
        ["Moodles_Thirst_desc_lvl4"] = "负重-2,体温严重升高,生命值缓慢下降",
        ["Moodles_Tired_desc_lvl1"] = "-50%近战伤害,视野范围缩小,耐力恢复大幅降低,搜索半径减小",
        ["Moodles_Tired_desc_lvl2"] = "-80%近战伤害,视野范围中等缩小,耐力恢复严重降低,搜索半径减小",
        ["Moodles_Tired_desc_lvl3"] = "-90%近战伤害,视野范围显著缩小,耐力恢复极度降低,搜索半径减小",
        ["Moodles_Tired_desc_lvl4"] = "-95%近战伤害,视野范围极度缩小,可在地面入睡,耐力恢复停止,搜索半径减小",
        ["Moodles_Uncomfortable_desc_lvl1"] = "衣物、护甲、环境或其他因素导致不适,不快乐感将持续上升",
        ["Moodles_Uncomfortable_desc_lvl2"] = "衣物、护甲、环境或其他因素导致中等程度的不快乐和不适",
        ["Moodles_Uncomfortable_desc_lvl3"] = "衣物、护甲、环境或其他因素导致严重的不快乐和不适",
        ["Moodles_Uncomfortable_desc_lvl4"] = "衣物、护甲、环境或其他因素导致极度不快乐和不适",
        ["Moodles_Unhappy_desc_lvl1"] = "读条行为速度-7.4%",
        ["Moodles_Unhappy_desc_lvl2"] = "读条行为速度-13.7%",
        ["Moodles_Unhappy_desc_lvl3"] = "读条行为速度-19.6%",
        ["Moodles_Unhappy_desc_lvl4"] = "读条行为速度-26.5%",
        ["Moodles_Wet_desc_lvl1"] = "因雨水或其他原因而潮湿",
        ["Moodles_Wet_desc_lvl2"] = "因雨水或其他原因而湿透",
        ["Moodles_Wet_desc_lvl3"] = "因雨水或其他原因而浸湿,患病几率增加",
        ["Moodles_Wet_desc_lvl4"] = "因雨水或其他原因而浑身湿透,极可能出现感冒症状",
        ["Moodles_Windchill_desc_lvl1"] = "体感温度降低5-10度",
        ["Moodles_Windchill_desc_lvl2"] = "体感温度降低10-15度",
        ["Moodles_Windchill_desc_lvl3"] = "体感温度降低15-20度",
        ["Moodles_Windchill_desc_lvl4"] = "体感温度降低超过20度",
        ["Moodles_zombified_desc_lvl1"] = "突然对枪声、警报声和人肉产生兴趣",
