        ["UI_Intro1"] = "我独自背负着",
        ["UI_Intro2"] = "一个黑暗到无法言说的真相,",
        ["UI_Intro3"] = "一段世界拒绝倾听的低语.",
        ["UI_News_Anim3"] = "<LINE> <LINE> <H1> 支持那些让《僵尸毁灭工程》保持活力的模组制作者!  <LINE> <TEXT> <LINE> <LINE> <LINE><SIZE:large> <RGB:0.8,0.8,0.0> 《僵尸毁灭工程》的蓬勃发展离不开出色的模组社区, 部分创作者甚至投入了数百乃至数千小时的个人时间, 为大家打造各类独特体验. 然而, 尽管付出了这般努力, 目前却没有任何机制能保障他们获得可持续的收益.  <LINE><LINE> <SIZE:large> <RGB:0.8,0.8,0.0> 如果你喜欢这些模组, 且希望看到它们持续更新进化, 不妨通过Steam模组页面上的捐赠渠道, 直接支持模组作者. 每一份捐助都能帮助他们继续创作, 不断优化那些让《僵尸毁灭工程》愈发精彩的内容.  <LINE><LINE><SIZE:large> <RGB:0.8,0.8,0.0> 《第一周》与《劫匪》这两款模组的开发, 耗费了大量时间、心血与耐心. 如果你喜欢这些模组, 别忘了在我的模组页面点个赞, 这是表达 appreciation 的简单方式!  <LINE><LINE><CENTRE> <SIZE:large> <RGB:0.8,0.8,0.8> 杀手 <LINE><LINE> ",
    },
