    ["\\DetailedDescriptionsForOccupationsAndTraits"] = {
        ["UI_profdesc_burglar"] = "知识:<br>- 制作前臂弹匣护甲<br>- 制作大腿弹匣护甲<br>- 制造小腿弹匣护甲<br>- 打造身体弹匣护甲<br>- 制作玻璃刀<br>- 制作刀<br>- 制作牙刷刀<br>- 复制建筑钥匙<br>- 制作空心书<br>- 制作前臂防弹背心护甲<br>- 制作小腿防弹背心护甲<br>- 制造大腿防弹背心盔甲<br>- 了解大麻生长季节<br><br>搜寻加成:<br>受天气影响减少 5%<br>受黑暗影响减少 15%<br>+10% 几率找到垃圾, 杂物, 垃圾武器和弹药<br>",
