        ["UI_profdesc_chef"] = "知识:<br>- 制作蛋糕棒<br>- 制作馅饼面团<br>- 制作面包面团<br>- 制造面包面团<br>- 制作饼干<br>- 制作巧克力饼干面团<br>- 制作巧克力碎片饼干面团<br>- 制作燕麦片饼干面团<br>- 制作短面包饼干面团<<br>- 制作糖饼干面团<br>- 制作披萨<br>- 制作炸洋葱圈<br>- 制作炸虾<br>- 制作寿司<br>- 制作饭团<br>- 制作寿司卷<br>- 做卷心菜卷<br>- 准备松饼<br>- 制作一罐农产品<br><br>搜寻加成:<br>+50% 的机会找到蘑菇<br>+20% 的机会发现浆果和野生草药<br>+15% 的机会找到垃圾食品和药用植物<br>+10% 10%的机会找到动物和野生植物<br>",
        ["UI_profdesc_constructionworker"] = "搜寻加成:<br>+10% 的机会找到垃圾和废弃物<br>",
        ["UI_profdesc_doctor"] = "搜寻加成:<br>+40% 找到医疗用品的机会<br>+10% 寻找药用植物的机会<br>",
        ["UI_profdesc_electrician"] = "可以操作发电机.<br><br>知识:<br>- 发电机<br>- 制造遥控器 V1<br>- 制造遥控器 V2<br>- 制造遥控器 V3<br>- 制造遥控触发器<br>- 制造计时器<br>- 制作简易收音机<br>- 制作简易无线电<br>- 制作简易对讲机<br>- 制造简易手电筒<br>- 制造简易提灯<br><br>搜寻加成:<br>+20% 的几率找到垃圾和废弃物<br>",
        ["UI_profdesc_engineer"] = "可以制造陷阱和爆炸物.<br><br>知识:<br>- 发电机<br>- 制造气溶胶炸弹<br>- 制造燃烧弹<br>- 制造管状炸弹<br>- 制造噪音发生器<br>- 制造烟雾弹<br>- 制造鞭炮<br>- 制造手工防毒面具过滤器<br>- 制造简易防毒面具<br>- 填充防毒面具过滤器<br>- 填充呼吸防护器过滤器<br>- 填充过滤器<br>- 制作一个简易的手电筒<br>- 制造简易提灯<br><br>搜寻加成:<br>+10% 的几率找到垃圾和废弃物<br>",
        ["UI_profdesc_farmer"] = "知识：<br>- 制作杀虫剂 (原料：香烟、散装烟草、嚼烟)<br>- 制作霉菌治疗剂<br>- 制作蚜虫治疗剂<br>- 制作稻草人<br>- 制作带刺铁丝网<br>- 所有作物生长季节 (大麻除外)<br>- 制作农产品罐<br><br>搜寻加成：<br>+1.5 视野半径<br>受天气影响减少33%<br>受黑暗影响减少10%<br>+50% 发现作物几率<br>+15% 发现野生草药几率<br>+10% 发现动物、水果和蔬菜几率<br>+5% 发现垃圾食品、药用植物和野生植物几率",
        ["UI_profdesc_fireofficer"] = "搜寻加成:<br>受天气影响减少5%<br>受黑暗影响减少10%<br>+20% 找到柴火的几率<br>+10% 找到垃圾的几率<br>",
        ["UI_profdesc_fisherman"] = "知识:<br>- 制作鱼竿<br>- 修复鱼竿<br>- 取出铁丝<br>- 制作渔网<br>- 制作鱼饵<br><br>特性:<br>+1.00 视觉半径<br>受天气影响减少 40%<br>黑暗影响减少 10%<br>+50% 几率找到昆虫或鱼饵<br>",
        ["UI_profdesc_fitnessInstructor"] = "搜寻加成:<br>+25% 的机会找到垃圾食品<br>+15% 寻找药用植物的机会<br>+5% 找到医疗用品, 野生植物和野生草本植物的机会<br>",
        ["UI_profdesc_lumberjack"] = "在森林和林地中移动稍快.<br>砍树时肌肉拉伤较少.<br><br>搜寻加成:<br>+1.25 视野半径<br>受天气影响减少33%<br>受黑暗影响减少15%<br>+50% 找到木材概率<br>+20% 找到蘑菇的概率<br>+5% 找到野生植物和草药的概率<br>",
        ["UI_profdesc_mechanics"] = "熟悉肯塔基道路上所有车型的维护和修理.<br><br>知识:<br>- 基础技工<br>- 中级技工<br>- 高级技工<br><br>特性:<br>+33% 几率找到垃圾和杂物<br>",
        ["UI_profdesc_metalworker"] = "可以焊接穿孔金属来制作物品和路障.<br><br>知识:<br>- 制作金属墙<br>- 制作金属围栏<br>- 制作金属容器<br>- 制作金属板<br>- 制作小金属板<br>- 制作金属屋顶<br>- 制作废金属头盔<br>- 制作废金属肩甲<br>- 制作废金属大腿甲<br>- 制作废金属防弹衣<br>- 钉子盔甲焊接<br><br>搜寻加成:<br>+10% 几率找到垃圾和废物<br>",
        ["UI_profdesc_nurse"] = "搜寻加成:<br>+40% 找到医疗用品的机会<br>+10% 寻找药用植物的机会<br>",
        ["UI_profdesc_parkranger"] = "在森林和林地中更快地移动.<br><br>知识:<br>- 制作棍子陷阱<br>- 制作圈套陷阱<br>- 制造木箱陷阱<br>- 制作陷阱盒<br>- 制作笼式陷阱<br><br>搜寻加成:<br>+2 视野半径<br>受天气影响减少33%<br>受黑暗影响减少15%<br>+75% 找到药用植物的概率<br>+50% 的几率找到野生植物和野生草药	<br>+20% 的几率发现浆果<br>+10% 的机会找到动物, 蘑菇和森林稀有植物<br>+5% 的几率找到垃圾和废弃物<br>",
