        ["UI_profdesc_securityguard"] = "搜寻加成:<br>受天气影响减少5%<br>受黑暗影响减少10%<br>+10% 找到垃圾, 废旧物品, 废旧武器和弹药的机会<br>",
        ["UI_profdesc_smither"] = "可以建造石炉和加工金属.<br>",
