        ["UI_profdesc_veteran"] = "搜寻加成:<br>+1.75 视觉半径<br>33% 受天气影响减少<br>15% 受黑暗影响减少<br>+50% 找到弹药的机会<br>+20% 寻找药用植物的机会<br>+10% 寻找野生植物和野菜的机会<br>+5% 寻找动物和森林稀有植物的机会<br>",
        ["UI_trait_AdrenalineJunkieDesc"] = "高度恐慌时移动速度更快.<br><br>+0.2 移动速度提升, 在严重恐慌时.<br>+0.25 移动速度提升.<br>",
        ["UI_trait_AllThumbsDesc"] = "缓慢转移物品. 走路时不能做任何东西.<br>绳索攀爬速度较慢, 坠落几率较高.<br>较慢的武器更换时间.<br><br>+100% 物品转移速度.<br>+20% 瞄准延迟.<br>武器卡壳的可能性增加.<br>",
