        ["UI_trait_AsthmaticDesc"] = "更快的耐力流失.<br><br>+40% 跑步/短跑时的耐力流失.<br>+20% 攻击时耐力损失.<br>",
        ["UI_trait_BarFighterDesc"] = "知识:<br>- 制作铁丝网武器<br>- 可以强化长武器<br>- 可以强化短武器<br>- 可以强化武器<br>- 了解钣金武器<br>",
        ["UI_trait_BlacksmithDesc"] = "可以使用铁砧制作金属物品.<br><br>知识:<br>- 锻造, 原始锻造和高级锻造<br>- 高炉, 冶炼炉和原始炉<br>- 木炭燃烧器和煤坑<br>- 粗糙的磨石<br>- 穹顶窑<br>- 临时电动鼓风机锻炉<br>- 从钢坯和铸锭中提取可加工铁<br>- 门把手和铰链<br>- 金属烹饪用具和餐具<br>- 金属工具, 刀, 刀片和剑<br>",
        ["UI_trait_BurglarDesc"] = "可以短接车辆, 打破窗户锁的可能性较小.<br><br>-50% 窗户锁被打破的可能性.<br>在爬墙和爬绳时摔倒的机会较小.<br>爬绳更快.<br>",
        ["UI_trait_ConspicuousDesc"] = "更有可能被僵尸发现.<br><br>+100% 被发现的机会.<br>",
        ["UI_trait_Cook2Desc"] = "知道烹饪食谱.<br><br>知识:<br>- 制作蛋糕棒<br>- 做馅饼面团<br>- 制作面包面团<br>- 制作法式长棍面包面团<br>- 饼干<br>- 制作饼干面团<br>- 制作巧克力屑饼干面团<br>- 制作燕麦饼干面团<br>- 制作酥饼面团<br>- 制作糖饼干面团<br>- 做披萨<br>- 制作炸洋葱圈<br>- 做炸虾<br>- 做卷心菜卷<br>- 制作一罐农产品<br><br>搜寻加成:<br>+0.2 视野半径<br>+5% 机会找到动物, 浆果, 蘑菇, 垃圾食品, 野生植物和野生草药<br>+3% 寻找药用植物的机会<br>",
        ["UI_trait_CookDesc"] = "知道烹饪食谱.<br><br>知识:<br>- 制作蛋糕棒<br>- 做馅饼面团<br>- 制作面包面团<br>- 制作法式长棍面包面团<br>- 制作饼干<br>- 制作饼干面团<br>- 制作巧克力屑饼干面团<br>- 制造燕麦片饼干面团<br>- 制作酥饼饼干面团<br>- 制作糖饼干面团<br>- 制作披萨<br>- 制作炸洋葱圈<br>- 制作炸虾<br>- 制作卷心菜卷<br>- 制作农产品一罐<br><br>搜寻加成:<br>+0.2 视野半径<br>+5% 的机会找到动物, 浆果, 蘑菇, 垃圾食品, 野生植物和野生草药<br>+3% 寻找药用植物的机会<br>",
        ["UI_trait_DesensitizedDesc"] = "不容易恐慌.<br><br>-85% 恐慌.<br>在尸体附近不会增加压力或不快乐.<br>做噩梦的几率更高.<br>",
        ["UI_trait_DexterousDesc"] = "快速转移物品.<br>绳索攀爬速度更快, 坠落几率更小.<br>更快的武器装备时间.<br><br>+50% 更快的物品转移速度.<br>-20% 瞄准延迟.<br>武器卡壳的可能性减少.<br>在没有开罐器的情况下打开罐头时受伤的几率较低.<br>",
        ["UI_trait_DismantlerDesc"] = "拆解速度更快.<br>",
        ["UI_trait_DisorganizedDesc"] = "容器容量减少.<br>影响世界各地的集装箱和袋子, 但不影响自己本身容量>-30% 容量.<br>",
        ["UI_trait_FastHealerDesc"] = "能从伤病中迅速康复.<br><br>-40% 伤病严重程度.<br>",
        ["UI_trait_FastLearnerDesc"] = "获得经验增加.<br><br>+30% 所有技能的经验值, 除了体能和力量.<br>",
        ["UI_trait_FastReaderDesc"] = "阅读书籍所需时间更少.<br><br>+30% 阅读速度.<br>",
        ["UI_trait_FirstAidDesc"] = "搜寻加成:<br>+3% 找到医疗用品的机会<br>",
        ["UI_trait_FishingDesc"] = "知识:<br>- 制作鱼竿<br>- 修理钓鱼竿<br>- 制作鱼饵<br><br>搜寻加成:<br>+5% 寻找昆虫和鱼饵的机会<br>",
        ["UI_trait_GardenerDesc"] = "知识：<br>- 制作杀虫剂 (原料：香烟 - 散装烟草 - 嚼烟)<br>- 制作霉菌治疗剂<br>- 制作蚜虫治疗剂<br>- 制作稻草人<br>- 所有作物生长季节 (大麻除外)<br>- 玫瑰、罂粟和薰衣草生长季节<br>- 制作农产品罐<br><br>搜寻加成：<br>+0.4 视野半径<br>受天气影响减少13%<br>+5% 发现作物、水果和蔬菜几率<br>+3% 发现药用植物几率<br>",
        ["UI_trait_GymnastDesc"] = "攀爬墙壁和绳索时摔倒的几率更少.<br>更快地攀爬绳索.<br>",
        ["UI_trait_HemophobicDesc"] = "自我急救时陷入恐慌.<br>不能对他人进行急救.<br>流血时会感到压力.<br>",
        ["UI_trait_HerbalistDesc"] = "可以找到草药, 工艺药和膏药.<br><br>知道野生食物是否有毒.<br><br>知识:<br>- 制作膏药: 车前草 - 聚合草 - 野生大蒜<br>- 生长季节: 黑鼠尾草 - 阔叶车前草 - 聚合草 - 锦葵 - 野生大蒜<br><br>搜寻加成:<br>+0.2 视野半径<br>+15% 寻找药用植物的机会<br>+5% 机会找到野生植物, 野生草药, 农作物, 浆果和蘑菇<br>",
        ["UI_trait_HighThirstDesc"] = "需要更多的水才能生存.<br><br>+100% 口渴.<br>",
        ["UI_trait_HikerDesc"] = "知识:<br>- 制作棍子陷阱<br>- 制作圈套陷阱<br>- 制作木箱陷阱<br><br>搜寻加成:<br>+0.7 视野半径<br>受天气影响减少13%<br>受黑暗影响减少3%<br>+3% 寻找药用植物, 浆果和蘑菇的机会<br>",
        ["UI_trait_HunterDesc"] = "知识:<br>- 制作棍子陷阱<br>- 制作圈套陷阱<br>- 制作木箱陷阱<br>- 制作陷阱盒<br>- 制作笼子陷阱<br><br>搜寻加成:<br>+0.5 视野半径<br>受天气影响减少13%<br>受黑暗影响减少5%<br>+5% 寻找动物的机会<br>+3% 寻找浆果, 蘑菇和药用植物的机会<br>",
        ["UI_trait_IlliterateDesc"] = "无法阅读任何书籍或文本.<br>",
        ["UI_trait_InconspicuousDesc"] = "不太可能被僵尸发现.<br><br>-50% 被发现的几率.<br>",
        ["UI_trait_InsomniacDesc"] = "睡眠时缓慢消除疲劳.<br><br>入睡需要两倍的时间.<br>-50% 睡眠时间.<br>-50% 睡眠时疲劳恢复.<br>",
        ["UI_trait_IronGutDesc"] = "食物中毒的机会更少.<br><br>-50% 食物中毒的机会.<br>-50% 食物中毒严重程度.<br>鸡蛋永远不会导致食物中毒.<br>",
        ["UI_trait_LessSleepDesc"] = "需要更少的睡眠.<br><br>-25% 睡眠时间.<br>-30% 疲劳率.<br>+25% 睡眠时疲劳恢复.<br>",
        ["UI_trait_LowThirstDesc"] = "需要更少的水就能生存.<br><br>-50% 口渴.<br>",
        ["UI_trait_MasonDesc"] = "更擅长建造石制和砖制建筑. <br><br>知识: <br>- 建造高级锻炉<br>- 建造高炉<br>- 建造圆顶窑<br>- 建造锻炉<br>- 建造熔炼炉<br>- 建造原始锻炉<br>",
        ["UI_trait_Mechanics2Desc"] = "熟悉肯塔基道路上所有车型的维护和修理.<br><br>知识:<br>- 基础技工<br>- 中级技工<br>- 高级技工<br>",
        ["UI_trait_MechanicsDesc"] = "了解常见和商用车型号知识以及维修.<br><br>知识:<br>- 基础技工<br>- 中级技工<br>",
        ["UI_trait_MetalWorkerDesc"] = "能够焊接收集来的金属以制造物品和路障.<br>",
        ["UI_trait_MoreSleepDesc"] = "需要更多睡眠.<br><br>+18% 睡眠时间.<br>+30% 疲劳率.<br>-18% 睡眠时疲劳恢复.<br>",
        ["UI_trait_NightVisionDesc"] = "夜间视力更好.<br><br>+20% 夜视能力.<br><br>搜寻加成:<br>+0.4 视野半径<br>受黑暗影响减少10%<br>",
        ["UI_trait_PacifistDesc"] = "战斗经验获得减少.<br><br>-25% 以下技能经验值:<br>- 小刀片和长刀片<br>- 小而钝的和长而钝的<br>- 矛<br>- 斧头<br>- 瞄准<br>",
        ["UI_trait_PackmuleDesc"] = "容器容量增加.<br><br>+30% 容量.<br>",
        ["UI_trait_PlaysBaseballDesc"] = "知识：雕刻球棒",
        ["UI_trait_PoorPassengerDesc"] = "有几率晕车.<br>",
        ["UI_trait_ScoutDesc"] = "搜寻加成:<br>+0.7 视野半径<br>受天气影响减少13%<br>+10% 找到垃圾的机会<br>+5% 寻找药用植物的机会<br>",
        ["UI_trait_SlowHealerDesc"] = "从伤病中缓慢恢复.<br><br>+60% 受伤严重程度.<br>",
        ["UI_trait_SlowLearnerDesc"] = "经验值获得减少.<br><br>-30% 所有技能的经验, 除了体格和力量.<br>",
        ["UI_trait_SlowReaderDesc"] = "阅读书籍和其他文学作品需要更长的时间.<br><br>-30% 阅读速度.<br>",
        ["UI_trait_SmokerDesc"] = "不吸烟会焦虑.<br>吸烟减轻焦虑和忧郁.<br>",
        ["UI_trait_SpeedDemonDesc"] = "热爱飙车.<br><br>+15% 车辆最高速度.<br>+15% 车辆加速和减速.<br>+15% 搬运尸体效率.<br>",
        ["UI_trait_SundayDriverDesc"] = "驾驶速度非常慢.<br><br>-40% 车辆最高速度.<br>-25% 车辆加速度.<br>-30% 倒车速度.<br>",
        ["UI_trait_TailorDesc"] = "知识：<br>- 编织：巴拉克拉头套 - 无檐小便帽 - 装饰桌巾 - 护腿袜套 - 围巾 - 袜子 - 毛衣背心 - 羊毛帽<br>- 缝制毛皮：靴子 - 裤子 - 外套 - 连帽衫 - 夹克 - 长袍 - 帽子 - 睡袋 - 钱包 - 腰包<br>- 缝制皮革：护裆 - 护颈 - 工具卷 - 手套 - 水袋 - 绑腿 - 护臂 - 裤子<br>- 制作油布：胸挂 - 背心 - 连衣裙<br>- 缝制粗制皮革背包<br>- 组装框架背包和高级框架背包<br>- 制作垃圾袋背心和连衣裙<br>- 编织麻绳鞋<br>- 缝制枪套和双枪套<br>- 制作西部靴<br>- 缝制腰带<br>- 缝制凉鞋<br>- 缝制弹药带和霰弹弹药带<br>- 缝制毛皮大衣和夹克<br>- 缝制护肘<br>- 缝制护膝<br>- 缝制布挎包<br>- 缝制及膝连衣裙和长连衣裙<br>- 缝制防寒内衣和防寒打底裤<br>- 缝制衬衫和无袖衬衫<br>- 缝制及膝裙和长裙<br>- 缝制长裤<br>",
        ["UI_trait_ThinSkinnedDesc"] = "被抓伤或咬伤的几率更高.<br><br>僵尸攻击使你受伤的可能性增加1.3倍.<br>更容易受到树木的划伤/割伤.<br>",
        ["UI_trait_WeakStomachDesc"] = "食物中毒的几率更高.<br><br>+100% 食物中毒的机会.<br>+100% 食物中毒严重程度.<br>",
        ["UI_trait_WhittlerDesc"] = "能够雕刻木制和骨制物品.<br><br>知识：<br>- 磨利骨头<br>- 制作骨制鱼钩<br>- 制作骨制缝衣针<br>- 磨利颌骨<br>- 雕刻编织针<br>- 雕刻球棒<br>- 制作骨制斧头<br>- 制作骨锥<br>- 制作大型骨珠<br>- 雕刻木叉<br>- 制作骨叉<br>- 雕刻木铲<br>- 雕刻高脚杯<br>- 雕刻木桶<br>- 雕刻剥皮工具<br>- 雕刻短棒<br>- 雕刻哨子<br><br>搜寻加成：<br>+30% 发现柴火几率<br>",
        ["UI_trait_WildernessKnowledgeDesc"] = "能够寻找药草并制作药物和膏药，并能制作简单的石制和骨制工具.<br><br>能够辨别野生食物是否有毒.<br><br>知识：<br>- 制作石制工具：刀刃 - 长刀刃 - 刀刃镰刀 - 锤头 - 锥子 - 凿子 - 钻头 - 大型斧头<br>- 制作骨制工具：鱼钩 - 缝衣针 - 骨锥 - 棍棒 - 短斧头 - 颌骨斧<br>- 制作粗糙磨刀石<br>- 制作石刃锯<br>- 长矛：捆扎、缠丝和火硬化处理<br>- 磨利长骨<br>- 制作钓竿<br>- 制作套索陷阱<br>- 雕刻木桶<br>- 雕刻剥皮工具<br>- 制作膏药：车前草 - 聚合草 - 野蒜<br><br>搜寻加成：<br>+0.4 视野半径<br>受天气影响减少13%<br>受黑暗影响减少5%<br>+5% 发现动物、浆果、蘑菇、药用植物、野生植物、野生草药、柴火和石头的几率<br>",
        ["UI_trait_agoraphobicdesc"] = "在户外时感到恐慌.<br><br>搜寻加成:<br>-1.5 视野半径<br>",
        ["UI_trait_athleticdesc"] = "更快的跑步速度.<br>可以跑得更久而不累.<br><br>+20% 的冲刺/跑步速度.<br>-40% 的跑步/冲刺耐力损失.<br>+25% 的尸体搬运效率.<br>",
        ["UI_trait_axemandesc"] = "更擅长砍树.<br>更快的挥动斧头.<br><br>+25% 的斧头挥动和砍树速度.<br>+50% 斧头砍树额外伤害.<br>",
        ["UI_trait_bravedesc"] = "不太容易恐慌.<br><br>-70% 恐慌和压力.<br>-50% 在尸体附近时的压力和不快乐率.<br>+10% 搬运尸体效率.<br>",
        ["UI_trait_broodingdesc"] = "从坏情绪中恢复较慢.<br>",
        ["UI_trait_claustrodesc"] = "在室内时感到恐慌.<br><br>大于70格的房间不会引起恐慌.<br>",
        ["UI_trait_clumsydesc"] = "移动时发出更大的噪音.<br><br>+10% 翻越后跌倒的几率.<br>+20% 脚步声.<br>爬墙和绳索时跌倒的几率很高.<br>撞到僵尸时跌倒的概率更高.<br>没有开罐器时开罐头更高概率伤到自己.<br>",
        ["UI_trait_cowardlydesc"] = "特别容易恐慌.<br><br>+100% 恐慌和压力.<br>+100% 在尸体附近时的压力和不快乐率.<br>-10% 搬运尸体效率.<br>",
        ["UI_trait_deafdesc"] = "聋了, 什么也听不见.<br>",
        ["UI_trait_eagleeyeddesc"] = "能见度衰减更快.<br>视野范围广.<br>武器瞄准器在远距离更有效.<br><br>搜寻加成:<br>+1.0 视野半径<br>",
        ["UI_trait_emaciateddesc"] = "低力量, 低耐力和更易受伤.<br><br>初始体重为50.<br>如果体重高于50, 则替换为身形消瘦<br>+40% 的坠落伤害和骨折/深部伤口的高几率.<br>-60% 的伤害.<br>-60% 的尸体搬运效率.<br>",
        ["UI_trait_feebledesc"] = "近战武器的击退更少.<br>携带重量减少.<br><br>-10% 携带重量.<br>",
        ["UI_trait_giftgabdesc"] = "超凡魅力.<br>获得NPC青睐的机会更大.<br>",
        ["UI_trait_gracefuldesc"] = "移动时噪音较小.<br><br>-10% 翻越后跌倒的几率.<br>+40% 脚步声降低.<br>撞到僵尸时跌倒的几率较小.<br>",
        ["UI_trait_handydesc"] = "建造速度更快且结构更坚固.<br><br>建造的木结构获得+100最大耐久度.<br><br>知识：<br>- 带刺铁丝网武器<br>- 螺栓球棒<br>- 制作刹车武器<br>- 制作水桶大锤<br>- 强化武器<br>- 制作园艺叉头武器<br>- 制作水壶大锤<br>- 道钉棒球棒<br>- 制作道钉短棍<br>- 制作道钉铁管<br>- 制作道钉长柄武器<br>- 制作道钉武器<br>- 制作耙头武器<br>- 制作锯片木板<br>- 制作锯片短棍<br>- 制作锯片长柄武器<br>- 制作锯片木板<br>- 制作锯片桌腿<br>- 制作锯片武器<br>- 金属板武器<br>- 制作铲头短棍<br>- 制作螺丝刀.<br>.",
        ["UI_trait_harddrinkdesc"] = "不容易喝醉.<br>",
        ["UI_trait_hardheardesc"] = "感知半径较小.<br>听力范围较小.<br>",
        ["UI_trait_heartyappetitedesc"] = "需要更频繁地进食.<br><br>+50% 饥饿.<br><br>搜寻加成:<br>+3% 的机会找到动物, 浆果, 蘑菇和垃圾食品<br>",
        ["UI_trait_hypochondesc"] = "可能在未感染的情况下出现感染症状.<br>",
        ["UI_trait_keenhearingdesc"] = "更大的感知半径.<br>",
        ["UI_trait_lightdrinkdesc"] = "醉得很快.<br>",
        ["UI_trait_lighteaterdesc"] = "需要的食物更少.<br><br>-25% 饥饿.<br>",
        ["UI_trait_luckydesc"] = "时来运转.<br>",
        ["UI_trait_marksmandesc"] = "提高了枪的精度和伤害.<br>更快的装弹.<br><br>搜寻加成:<br>+0.5 视野半径<br>+3% 找到弹药的几率<br>",
        ["UI_trait_nightowldesc"] = "需要很少的睡眠.<br>即使在睡觉时也能保持额外的警觉.<br><br>入睡所需的时间更少.<br>+40% 睡眠疲劳恢复.<br>",
        ["UI_trait_nutritionist2desc"] = "可以看到任何食物的营养价值.<br><br>搜寻加成:<br>+0.2 视野半径<br>+5% 的机会找到垃圾食品, 药用植物, 野生植物和野生草本植物<br>",
        ["UI_trait_nutritionistdesc"] = "可以看到任何食物的营养价值.<br><br>搜寻加成:<br>+0.2 视野半径<br>+5% 的机会找到垃圾食品, 药用植物, 野生植物和野生草本植物<br>",
        ["UI_trait_obesedesc"] = "奔跑速度降低，耐力极差且容易受伤.<br><br>+20% 翻越后摔倒的几率.<br>初始体重为105.<br>如果体重低于100, 则由超重代替.<br>+40% 跌倒伤害,高概率导致骨折/深部伤口.<br>爬攀爬速度更慢且高概率摔倒.<br>撞到僵尸时跌倒的几率更高.<br>+5% 搬运尸体效率.<br>",
        ["UI_trait_outdoorsmandesc"] = "受恶劣天气条件的影响较小。<br><br>生火速度更快且引火物损坏几率更低。<br>感冒几率 -75%<br>行走时被树木损伤的几率极低。<br>奔跑时被树木损伤的几率非常低。<br>受天气影响 -50%<br><br>搜寻加成：<br>视野半径 +0.4<br>受天气影响减少 13%<br>受黑暗影响减少 5%<br>发现动物、浆果、蘑菇、药用植物、野生植物和野生草药几率 +5%<br>",
        ["UI_trait_outofshapedesc"] = "低耐力, 较少的耐力恢复.<br>",
        ["UI_trait_overweightdesc"] = "跑步速度降低, 耐力低, 容易受伤.<br><br>+10% 翻越后的跌倒的几率.<br>初始体重为 95.<br>如果体重高于100, 则会变为身体肥胖.<br>如果体重低于85, 则移除过重特征.<br>+20% 跌倒伤害, 骨折/深部伤口的几率略高.<br>爬得较慢, 跌倒的几率适中.<br>撞到僵尸时跌倒的几率更高.<br>+10% 尸体搬运效率.<br>",
        ["UI_trait_patientdesc"] = "不容易生气.<br>",
        ["UI_trait_pronetoillnessdesc"] = "更容易患病.<br>僵尸化速率更快.<br><br>+70% 感冒几率.<br>+50% 感冒进展率.<br>+20% 感冒强度.<br>-25% 尸变时间.<br>+25% 尸体病率.<br>",
        ["UI_trait_resilientdesc"] = "较不易患病.<br>僵尸化速率较慢.<br><br>-55% 感冒几率.<br>-50% 感冒进展率.<br>-20% 感冒强度.<br>+25% 尸变时间.<br>-25% 尸体病率.<br>",
        ["UI_trait_shortsighdesc"] = "视野距较小.<br>可见度衰减较慢.<br>武器瞄准器效果较差.<br><br>在角色半径外应用屏幕模糊效果.<br>戴眼镜会消除屏幕模糊效果及武器瞄准和搜寻减益.<br><br>搜寻加成:<br>-2 视野半径<br>",
        ["UI_trait_shorttemperdesc"] = "十分容易生气.<br>",
        ["UI_trait_stoutdesc"] = "近战武器的额外击退.<br>携带重量增加.<br><br>+25% 携带重量.<br>",
        ["UI_trait_strongdesc"] = "近战武器有额外击退.<br>增加携带重.<br><br>+50% 携带重量.<br>+40% 击退力.<br>+25% 尸体搬运效率.<br>",
        ["UI_trait_thickskinneddesc"] = "被抓伤或咬伤的几率较低.<br><br>僵尸攻击使你受伤的可能性降低1.3倍.<br>提供轻微的树木划痕/割伤防护.<br>",
        ["UI_trait_underweightdesc"] = "力量低, 耐力低, 容易受伤.<br><br>+10% 翻越后摔倒的几率.<br>起始重量为70.<br>如果重量低于65, 则替换为身形消瘦<br>如果重量高于75, 则移除体重过轻特征.<br>-20% 的伤害.<br>撞到僵尸时摔倒的几率更高.<br>-20% 的尸体搬运效率.<br>",
        ["UI_trait_unfitdesc"] = "耐力和耐力恢复非常低.<br>",
        ["UI_trait_unluckydesc"] = "陷入了灾厄的洪流! .<br>",
        ["UI_trait_veryunderweightdesc"] = "力量非常低, 耐力非常低, 容易受伤.<br><br>+20% 翻越后摔倒的几率.<br>初始体重为60.<br>如果体重低于50, 则会变成瘦骨嶙峋.<br>如果重量高于65, 则由体重过轻代替.<br>+20% 摔倒伤害, 骨折/深伤口的几率略高.<br>-40% 造成的伤害.<br>撞到僵尸时摔倒的几率更高.<br>-40% 的尸体搬运效率.<br>",
        ["UI_trait_weakdesc"] = "近战武器的击退要少得多.<br>携带重量极小.<br><br>-25% 携带重量.<br>-40% 击退力.<br>",
        ["UI_trait_weightgaindesc"] = "永久性增重倾向, 初始体重高.<br><br>+16% 的卡路里获取.<br>有高体重问题<br>",
        ["UI_trait_weightlossdesc"] = "永久性减肥倾向, 初始体重低.<br><br>+75% 开始增重所需的卡路里.<br>",
    },
