    ["\\LifestyleHobbies"] = {
        ["UI_trait_IronGutDesc"] = "患食物疾病的几率更低.<br><br>膀胱更强,能够忍耐更久,使用洗手间的频率更低.",
        ["UI_trait_WeakStomachDesc"] = "更容易患食物疾病.<br><br>膀胱较弱,几乎无法忍耐,需要更频繁地使用洗手间.",
        ["UI_trait_artistic"] = "艺术天赋",
