        ["UI_trait_cleanfreak"] = "洁癖",
        ["UI_trait_cleanfreakdesc"] = "他们在清洁中找到慰藉,对生活在一尘不染的环境中有一种强迫性的需求.<br><br>几乎无法容忍脏乱的环境.<br><RGB:1,0.8,0> 清洁 <RGB:1,1,1><SPACE> 执行时间更长.",
        ["UI_trait_couchpotato"] = "沙发土豆",
        ["UI_trait_couchpotatodesc"] = "他们更愿意待在家里,享受 <SPACE><RGB:1,0.8,0> 舒适 <RGB:1,1,1>.<br><br>更容易疲劳,睡眠更频繁.<br>喜欢被动娱乐.<br>在室内时,无聊感积累更慢.<br>不喜欢 <SPACE><RGB:1,0.8,0> 冥想 <RGB:1,1,1><SPACE> 和待在户外.",
        ["UI_trait_disciplined"] = "自律",
        ["UI_trait_disciplineddesc"] = "勤奋专注,不断努力提升自我,他们成为出色的 <SPACE><RGB:1,0.8,0> 武术家 <RGB:1,1,1><SPACE> 和 <SPACE><RGB:1,0.8,0> 冥想 <RGB:1,1,1><SPACE> 大师.<br><br>对被动娱乐不太感兴趣.<br><RGB:1,0.8,0> 舒适 <RGB:1,1,1><SPACE> 需求——减少速率和正/负效果.",
        ["UI_trait_killjoy"] = "扫兴鬼",
        ["UI_trait_killjoydesc"] = "大型人群、大声音乐和狂热的能量并不是你的菜.",
        ["UI_trait_outdoorsmandesc"] = "不受恶劣天气条件的影响.<br><br>在户外排尿时情绪惩罚更小.",
        ["UI_trait_partyanimal"] = "派对动物",
        ["UI_trait_partyanimaldesc"] = "派对的灵魂人物,也是天赋异禀的 <SPACE><RGB:1,0.8,0> 舞者 <RGB:1,1,1><SPACE>,随时准备踏上舞池,保持高能量.",
        ["UI_trait_sloppy"] = "邋遢",
        ["UI_trait_sloppydesc"] = "整洁不是他们的优先事项.<br><br>对脏乱环境的容忍度更高.<br>讨厌 <SPACE><RGB:1,0.8,0> 清洁 <RGB:1,1,1><SPACE>,执行时间更长.<br>几乎从不主动冲洗马桶.<br>更容易堵塞马桶.<br>在流血/脏污时以及制作物品时,产生血迹/污垢和垃圾的几率更高.",
        ["UI_trait_tidy"] = "整洁",
        ["UI_trait_tidydesc"] = "保持居住空间的清洁对他们来说很容易.<br><br>在流血/脏污时以及制作物品时,产生血迹/污垢和垃圾的几率更低.<br>喜欢 <SPACE><RGB:1,0.8,0> 清洁 <RGB:1,1,1><SPACE>,并且执行速度更快.",
        ["UI_trait_tonedeaf"] = "五音不全",
