        ["UI_prof_unemployed"] = "失业者",
        ["UI_profdesc_carpenter"] = "精通木工的专家——可以是细木工、古董修复师、普通木匠等类似职业.",
        ["UI_profdesc_chef"] = "在专业厨房工作的人, 例如主厨或副主厨.",
        ["UI_profdesc_constructionworker"] = "专精建筑和翻新的强壮工人.",
        ["UI_profdesc_doctor"] = "医学毕业生. <br>可代表任何类型的医生——添加裁缝特质成为外科医生, 模范学生成为研究员, 或用此方法创建你的角色.",
        ["UI_profdesc_electrician"] = "电子专家——可以是计算机高手、电工或任何处理电子或电力的角色.",
        ["UI_profdesc_farmer"] = "与植物和植被打交道以生产植物产品的人.",
        ["UI_profdesc_fireofficer"] = "消防员是冒着生命危险保护平民的英雄, 他们体魄强健且性格勇敢.<br>选择驾驶爱好者成为消防车司机, 或添加其他特质进一步专精.",
        ["UI_profdesc_fisherman"] = "渔夫以生产或捕捞鱼类食物为生.",
        ["UI_profdesc_fitnessInstructor"] = "前运动员, 现从事某项运动或体能活动的青年培训. <br>适合: 武术教练、私人教练、拳击教练、瑜伽导师、舞蹈教练、团队教练、学校教练等类似角色. <br>使用现有特质进一步专精此职业.",
        ["UI_profdesc_mechanics"] = "精通肯塔基州道路上所有车辆维护修理的专家.<br>可代表船舶、军用或航空机械师、车身修理师、汽车电工等职业.",
        ["UI_profdesc_metalworker"] = "使用焊接技术制造物品和金属路障的金属工人.",
        ["UI_profdesc_nurse"] = "协助医生完成次要医疗工作或从事不需要医学学位的医护工作. <br>选择特质可专精, 如营养师成为饮食专家, 急救员成为护士等.",
        ["UI_profdesc_parkranger"] = "致力于保护森林、野生动物和公共绿地的准军事部队成员.",
        ["UI_profdesc_policeofficer"] = "警察惯于处理犯罪分子和违法行为, 受过枪械使用训练, 是法律的执行者.",
        ["UI_profdesc_rancher"] = "饲养牲畜以生产肉类和动物产品的牧场主.",
        ["UI_profdesc_repairman"] = "擅长修理物品、家具、电器、机械和系统的杂工. <br>可以是电话技术员、钟表匠、机械师或类似行业.",
        ["UI_profdesc_securityguard"] = "负责场所、物品或人员安全的私人警察. <br>选择特质可专精此职业, 如健壮或强壮成为保镖, 夜猫子成为守夜人, 或警觉成为狱警.",
        ["UI_profdesc_smither"] = "能够用金属锻造任何东西的强壮金属工人.",
        ["UI_profdesc_unemployed"] = "抑郁? 懒惰? 运气不好? 退休了? 无论什么原因, 你已经失业一段时间了. <br>你可以通过选择特质进一步专精: <br>选择耳聋或许多身体缺陷成为残疾人<br>选择年长成为退休人员<br>选择杂乱无章成为无业人员<br>选择年轻成为不在学校的20多岁年轻人<br>或使用此方法创建你自己的角色.",
        ["UI_profdesc_veteran"] = "军队成员.",
        ["UI_profdesc_xp1"] = "%1 经验值加成",
        ["UI_profdesc_xp2"] = "%1 大量经验值加成",
        ["UI_profdesc_xp3"] = "%1 巨额经验值加成",
        ["UI_trait_AllThumbs"] = "笨手笨脚 (动态)",
        ["UI_trait_AllThumbsDesc"] = "转移物品的速度较慢.<br>无法在行走时进行建造.<br>爬绳子时速度更慢, 且坠落风险更高.<br>拔出武器的速度更慢.<br>当你的敏捷属性足够高时, 该特质会被移除.",
        ["UI_trait_Artisan"] = "工匠 (动态)",
        ["UI_trait_ArtisanDesc"] = "你可以加工玻璃和陶瓷.<br>在相关技能达到足够等级后会获得该特质.",
        ["UI_trait_Asthmatic"] = "体弱",
        ["UI_trait_AsthmaticDesc"] = "患有疾病、病症或无法治愈的综合征.<br>体力消耗更快.<br>开局时携带维生素片.",
        ["UI_trait_BarFighter"] = "酒吧斗殴者 (动态)",
        ["UI_trait_BarFighterDesc"] = "你总是随时准备战斗.<br>当你击杀 700 只僵尸并拥有足够相关技能等级时会获得该特质.<br>末日开始时你会拥有一根钉刺棒球棍.",
        ["UI_trait_Blacksmith"] = "金属加工知识 (动态)",
        ["UI_trait_Blacksmith2"] = "金属加工知识",
        ["UI_trait_BlacksmithDesc"] = "知道如何使用铁砧制造金属物品.<br>当锻造技能达到 5 级时会获得该特质.<br>开局时携带一把铁匠锤.",
        ["UI_trait_BurglarDesc"] = "可以搭线启动车辆. <br>弄坏车窗锁的可能性更低.",
        ["UI_trait_Conspicuous"] = "显眼 (动态)",
        ["UI_trait_ConspicuousDesc"] = "更容易被僵尸发现.<br>当你的潜行相关技能足够高时, 该特质会被移除.",
        ["UI_trait_Cook"] = "烹饪爱好者 (动态)",
        ["UI_trait_CookDesc"] = "掌握烹饪配方.<br>当烹饪技能达到 4 级时会获得该特质.<br>开局时携带一些罐头食品.",
        ["UI_trait_Crafty"] = "巧匠 (动态)",
        ["UI_trait_CraftyDesc"] = "你更偏好实践而非理论.<br>合成类技能的经验获取提升.",
        ["UI_trait_Desensitized"] = "麻木不仁 (动态)",
        ["UI_trait_DesensitizedDesc"] = "极少陷入恐慌.<br>当角色击杀 1000 只僵尸后会变得麻木不仁, 完全失去对丧尸的恐惧.",
        ["UI_trait_Dexterous"] = "灵巧 (动态)",
        ["UI_trait_DexterousDesc"] = "转移物品速度更快.<br>爬绳子更快, 且坠落风险更低.<br>拔出武器更快.<br>当灵活技能达到 7 级时获得该特质.<br>在遭受严重的身体创伤后有极小概率失去该特质.",
        ["UI_trait_DismantlerDesc"] = "拆解物品的速度更快.",
        ["UI_trait_Disorganized"] = "杂乱无章 (动态)",
        ["UI_trait_DisorganizedDesc"] = "物品栏容量降低.<br>通过频繁搬运大量物品有机会移除该特质.",
        ["UI_trait_FastHealer"] = "高效免疫系统",
        ["UI_trait_FastHealerDesc"] = "伤口和疾病的恢复速度更快.",
        ["UI_trait_FastLearner"] = "快速学习者 (动态)",
        ["UI_trait_FastLearnerDesc"] = "获得的经验值更多.<br>在阅读 10000 页书籍并提升足够的相关技能后会获得该特质.",
        ["UI_trait_FastReader"] = "快速阅读者 (动态)",
        ["UI_trait_FastReaderDesc"] = "阅读书籍所花时间更少.<br>在阅读 4000 页书籍后, 且不再拥有阅读缓慢特质时, 会获得该特质.<br>开局时携带一本书.",
        ["UI_trait_FirstAid"] = "急救 (动态)",
        ["UI_trait_FirstAid2Desc"] = "你具备基本的复苏和急救知识.",
        ["UI_trait_FirstAidDesc"] = "你具备基本的复苏和急救知识.<br>当相关技能达到足够等级时会获得该特质.<br>开局时携带一条消毒绷带.",
        ["UI_trait_Fishing"] = "渔夫 (动态)",
        ["UI_trait_Fishing2"] = "渔夫",
        ["UI_trait_Fishing2Desc"] = "你喜欢钓鱼.",
        ["UI_trait_FishingDesc"] = "你喜欢钓鱼.<br>当相关技能达到足够等级时会获得该特质.<br>开局时携带一根鱼竿.",
        ["UI_trait_Gardener"] = "园艺高手 (动态)",
        ["UI_trait_Gardener2Desc"] = "你热爱植物和树木, 并且擅长照顾它们.",
        ["UI_trait_GardenerDesc"] = "你热爱植物和树木, 并且擅长照顾它们.<br>当相关技能达到足够等级时会获得该特质.<br>开局时携带一把园艺叉.",
        ["UI_trait_Hemophobic"] = "晕血症 (动态)",
        ["UI_trait_HemophobicDesc"] = "为自己进行急救时会恐慌.<br>无法为他人进行急救.<br>身上沾血时会感到更大的压力.<br>拥有恐惧血液特质的角色在击杀 150 只僵尸后可以克服对血的恐惧.",
        ["UI_trait_Herbalist"] = "草药师 (动态)",
        ["UI_trait_HerbalistDesc"] = "能寻找药用草药并制作药物和膏药.<br>通过阅读草药学杂志获得该特质.<br>开局时携带研钵和研杵.",
        ["UI_trait_HighThirstDesc"] = "生存所需的水更多.<br>开局时携带一瓶水.",
        ["UI_trait_Hiker"] = "徒步旅行者 (动态)",
        ["UI_trait_HikerDesc"] = "习惯在自然环境中长途步行.<br>当相关技能达到足够等级时会获得该特质.<br>开局时携带一顶帐篷.",
        ["UI_trait_Hunter"] = "猎人 (动态)",
        ["UI_trait_HunterDesc"] = "当相关技能达到足够等级时会获得该特质.",
        ["UI_trait_Illiterate"] = "文盲 (动态)",
        ["UI_trait_IlliterateDesc"] = "无法阅读书籍或世界中的文字内容.<br>拥有该特质的玩家可以通过阅读逐渐克服文盲状态.<br>只需将书装备在手中并让时间流逝.<br>游戏会记录阅读时间, 当累计阅读达到 1000 小时后, 文盲特质会被移除并替换为慢读者.<br>自学识字很困难, 因此需要花费大量时间.<br>只有简单读物会被计入, 如小说类书籍或八卦杂志; 技能书和配方杂志对文盲角色来说过于复杂, 不会计入.",
        ["UI_trait_Inconspicuous"] = "不显眼 (动态)",
        ["UI_trait_InconspicuousDesc"] = "更不容易被僵尸发现.<br>当潜行和轻巧技能都达到 5 级时会获得该特质.",
        ["UI_trait_Insomniac"] = "失眠症",
        ["UI_trait_InsomniacDesc"] = "睡觉时疲劳恢复速度减慢.<br>容易频繁醒来, 做噩梦或睡得不安稳.<br>开局时携带安眠药片.",
        ["UI_trait_IronGutDesc"] = "食物中毒风险更低.",
        ["UI_trait_Jogger"] = "慢跑者 (动态)",
        ["UI_trait_JoggerDesc"] = "你喜欢跑步.<br>当相关技能达到足够等级时会获得该特质.<br>开局时携带一瓶水.",
        ["UI_trait_LessSleep"] = "浅眠者",
        ["UI_trait_LessSleepDesc"] = "需要的睡眠时间更少.<br>开局时携带安眠药片.",
        ["UI_trait_Mechanics"] = "车辆知识 (动态)",
        ["UI_trait_Mechanics2Desc"] = "具备常见和商用车辆型号及其维修的知识.",
        ["UI_trait_MechanicsDesc"] = "具备常见和商用车辆型号及其维修的知识. <br>在机械技能达到3级后获得此特质. <br>你开局带有一把扳手.",
        ["UI_trait_Metalworker"] = "焊工 (动态)",
        ["UI_trait_MetalworkerDesc"] = "精通焊接. <br>在金属加工等级达到4级时获得此特质. <br>开局带有焊接面具和喷灯.",
        ["UI_trait_MoreSleep"] = "沉睡者",
        ["UI_trait_MoreSleepDesc"] = "需要更多睡眠.<br>开局时携带维生素片.",
        ["UI_trait_NightVision"] = "猫眼",
        ["UI_trait_NightVisionDesc"] = "在夜间拥有更好的视野.<br>开局时携带一副太阳镜.",
        ["UI_trait_Pacifist"] = "和平主义者 (动态)",
        ["UI_trait_PacifistDesc"] = "战斗中获得更少经验值. <br>当你杀死150个僵尸后, 此特质将被移除. <br>如果你长时间不杀僵尸, 可能会获得此特质.",
        ["UI_trait_Packmule"] = "有条理 (动态)",
        ["UI_trait_PackmuleDesc"] = "物品栏容量增加.<br>通过搬运大量物品可以获得该特质.<br>开局时携带一支钢笔和一本日记本.",
        ["UI_trait_PlaysBaseballDesc"] = "你热爱打棒球.<br>开局时携带一根棒球棒.",
        ["UI_trait_PoorPassenger"] = "晕车",
        ["UI_trait_PoorPassengerDesc"] = "车辆行驶时会出现晕车反应.",
        ["UI_trait_Scout"] = "童子军",
        ["UI_trait_ScoutDesc"] = "你是或曾是童子军.<br>初始携带一些火柴.",
        ["UI_trait_SelfDefenseClass"] = "自卫术",
        ["UI_trait_SelfDefenseClassDesc"] = "你练习过武术或专注于徒手格斗的格斗运动.<br>初始携带一根强化棍棒.",
        ["UI_trait_SlowHealer"] = "低效免疫系统",
        ["UI_trait_SlowHealerDesc"] = "伤口和疾病的恢复速度更慢.",
        ["UI_trait_SlowLearner"] = "慢速学习者 (动态)",
        ["UI_trait_SlowLearnerDesc"] = "获得的经验值更少.<br>在大量阅读并提升足够的技能等级后, 此特质将被移除.",
        ["UI_trait_SlowReader"] = "慢速阅读者 (动态)",
        ["UI_trait_SlowReaderDesc"] = "阅读书籍所需时间更长.<br>在阅读 1000 页后会失去此特质.",
        ["UI_trait_Smoker"] = "吸烟者 (动态)",
        ["UI_trait_SmokerDesc"] = "吸食烟草后压力和不开心会下降.<br>不吸烟时不开心会逐渐上升.<br>如果角色在 20 个游戏日内戒烟且未经历戒断, 可以失去该特质, 也可以通过吸烟获得该特质.<br>开局携带香烟和打火机.",
        ["UI_trait_SpeedDemon"] = "超速狂魔 (动态)",
        ["UI_trait_SpeedDemonDesc"] = "驾驶速度非常快.<br>在驾驶技能达到 7 级时会获得此特质.",
        ["UI_trait_SundayDriver"] = "周日司机 (动态)",
        ["UI_trait_SundayDriverDesc"] = "驾驶速度非常慢.<br>在驾驶技能达到 3 级时会失去此特质.",
        ["UI_trait_Tailor"] = "裁缝 (动态)",
        ["UI_trait_TailorDesc"] = "缝纫技能. <br>开局带有针和线. <br>在裁缝技能达到4级后获得此特质.",
        ["UI_trait_ThinSkinned"] = "皮薄 (动态)",
        ["UI_trait_ThinSkinnedDesc"] = "被抓伤或咬伤的几率更高. <br>在遭受多次创伤后, 此特质会被移除.",
        ["UI_trait_WeakStomachDesc"] = "食物中毒风险更高.",
        ["UI_trait_Whittler"] = "削木工 (动态)",
        ["UI_trait_WhittlerDesc"] = "可以用木材和骨头雕刻物品.<br>初始携带一把削皮小刀.<br>当雕刻相关技能达到足够等级时会获得此特质.",
        ["UI_trait_WildernessKnowledge"] = "荒野求生技能 (动态)",
        ["UI_trait_WildernessKnowledgeDesc"] = "能寻找药用草药、制作药物和膏药, 以及用石头和骨头制作简单工具.<br>当你拥有草药师特质并达到足够的相关技能等级时会获得此特质.<br>包含草药师配方.<br>开局携带火柴、帐篷和猎刀.",
        ["UI_trait_agoraphobic"] = "开阔恐惧 (动态)",
        ["UI_trait_agoraphobicdesc"] = "在户外时会陷入恐慌.<br>开局携带β受体阻滞剂药片.<br>开阔恐惧角色在户外累计待满 4000 小时后会战胜恐惧.<br> (时间根据游戏中正常的恐慌恢复机制计算.)",
        ["UI_trait_artistic"] = "艺术之魂 (动态)",
        ["UI_trait_artisticdesc"] = "天生具有艺术才华, 从<SPACE><RGB:1,0.8,0>艺术<RGB:1,1,1><SPACE>相关爱好中获得强大增益, 也可能成为优秀作家.",
        ["UI_trait_athletic"] = "运动健将 (动态)",
        ["UI_trait_athleticdesc"] = "跑得更快.<br>可以跑更久而不容易疲劳.<br>普通人的体能水平对应体能等级 5.<br>体能等级达到 8 级时会获得此特质.",
        ["UI_trait_axeman"] = "斧术大师",
        ["UI_trait_axemandesc"] = "更擅长砍伐树木.<br>挥斧速度更快.",
        ["UI_trait_brave"] = "无所畏惧 (动态)",
        ["UI_trait_bravedesc"] = "更不容易陷入恐慌.<br>当角色击杀 500 只僵尸后会获得无所畏惧特质.",
        ["UI_trait_broodingdesc"] = "从坏心情中恢复需要更长时间.",
        ["UI_trait_claustro"] = "幽闭恐惧症 (动态)",
        ["UI_trait_claustrodesc"] = "在室内时会陷入恐慌.<br>幽闭恐惧症角色在建筑物内累计待满 4,000 小时后会战胜恐惧.<br> (时间根据游戏中标准的恐慌恢复机制计算.)",
        ["UI_trait_cleanfreak"] = "洁癖 (动态)",
        ["UI_trait_cleanfreakdesc"] = "在清洁中找到慰藉, 有强迫性需求必须生活在整洁干净的空间.<br>无法容忍肮脏的环境. <br><RGB:1,0.8,0>清洁<RGB:1,1,1><SPACE>耗时更久.",
        ["UI_trait_clumsy"] = "笨拙 (动态)",
        ["UI_trait_clumsydesc"] = "移动时更容易发出噪音.<br>当潜行相关技能达到足够等级时会失去此特质.",
        ["UI_trait_couchpotato"] = "沙发土豆 (动态)",
        ["UI_trait_couchpotatodesc"] = "沙发土豆不爱运动, 更喜欢放松享受舒适. <br>需要鼓励才会进行体力活动. <br>游戏、收音机和电视能更有效减少无聊, 技能节目提供更多经验值. <br>获得的舒适加成更高但衰减更快. <br>能在室内待更久才感到无聊, 但户外活动太久会产生压力. <br>更容易疲劳且比常人睡得更多. <br>讨厌大多数体力爱好, 被迫进行时会很快变得不快乐或无聊.",
        ["UI_trait_cowardly"] = "畏首畏尾 (动态)",
        ["UI_trait_cowardlydesc"] = "极易陷入恐慌.<br>如果角色击杀 250 只僵尸, 将失去此特质.",
        ["UI_trait_deaf"] = "耳聋 (动态)",
        ["UI_trait_deafdesc"] = "听不到任何声音.<br>在遭受严重听觉创伤后可能获得此特质.<br>创伤痊愈后有机会自动失去该特质.",
        ["UI_trait_disciplined"] = "自律 (动态)",
        ["UI_trait_disciplineddesc"] = "自律者勤奋专注, 不断自我提升. <br>拥有强大意志力和决心, 在战斗和困境中表现出色. <br>练习冥想和武术时最快乐. <br>不关心电子娱乐, 从技能电视节目获得的经验值减少. <br>比常人更能忍受不适.",
        ["UI_trait_driver"] = "驾驶爱好者",
        ["UI_trait_eagleeyed"] = "鹰眼",
        ["UI_trait_eagleeyeddesc"] = "视野衰减更慢.<br>视野范围更宽.<br>远距离瞄准能力更好.",
        ["UI_trait_emaciated"] = "消瘦 (动态)",
        ["UI_trait_emaciateddesc"] = "力量和耐力较低, 更容易受伤.",
        ["UI_trait_feeble"] = "虚弱 (动态)",
        ["UI_trait_feebledesc"] = "近战武器的击退效果较弱.<br>负重能力降低.<br>普通人的力量水平对应力量等级 5.<br>当你的力量略低于平均水平时会获得此特质.",
        ["UI_trait_fit"] = "健壮 (动态)",
        ["UI_trait_fitdesc"] = "普通人的体能水平对应体能等级 5.<br>体能等级达到 6 级时会获得此特质.",
        ["UI_trait_giftgab"] = "能言善道",
        ["UI_trait_giftgabdesc"] = "魅力极高.<br>更容易从 NPC 那里获得帮助和好处.",
        ["UI_trait_graceful"] = "优雅 (动态)",
        ["UI_trait_gracefuldesc"] = "移动时产生的噪音更少.<br>在灵巧、潜行和轻足三项技能都达到 3 级后会获得此特质.<br>当力量达到 9 级时会失去此特质, 因为过于健壮的身材难以保持如此优雅的动作.",
        ["UI_trait_handy"] = "手巧 (动态)",
        ["UI_trait_handydesc"] = "建造速度更快, 建筑更加坚固.<br>开局携带一把锤子和一盒钉子.<br>在维护、钝器和木工技能达到足够等级后会自动获得此特质.",
        ["UI_trait_harddrink"] = "豪饮者 (动态)",
        ["UI_trait_harddrinkdesc"] = "喜欢喝酒.<br>不容易喝醉, 几乎不会醉醺醺.<br>不会发展成酒鬼.<br>如果每天喝酒却始终没有获得“酒鬼”特质, 久而久之会获得此特质.<br>长时间停止饮酒则会失去此特质.<br>开局携带一个酒壶.",
        ["UI_trait_hardhear"] = "听力障碍 (动态)",
        ["UI_trait_hardheardesc"] = "感知范围缩短, 听觉距离降低.<br>如果在创建人物时选择此特质, 唯一的移除方式是变成耳聋.<br>在经历严重创伤, 或长期每天使用枪械后, 可能会获得此特质.<br>使用耳机可以保护听力.<br>若因创伤获得此特质, 创伤痊愈后有机会失去它.",
        ["UI_trait_heartyappetite"] = "大胃王",
        ["UI_trait_heartyappetitedesc"] = "需要更频繁地进食.<br>开局携带一份零食.",
        ["UI_trait_keenhearing"] = "听觉敏锐 (动态)",
        ["UI_trait_keenhearingdesc"] = "感知范围增加, 听觉更加敏锐.<br>此特质无法通过游戏过程获得, 只能在创建时选择.<br>在经历严重创伤, 或长期每天使用枪械后, 可能会失去此特质.<br>使用耳机可以保护听力.<br>若因创伤失去此特质, 创伤痊愈后有机会重新获得.",
        ["UI_trait_killjoy"] = "扫兴鬼 (动态)",
        ["UI_trait_killjoydesc"] = "大群人、吵闹音乐和疯狂能量从来不是你的菜.",
        ["UI_trait_lightdrink"] = "轻量饮酒者 (动态)",
        ["UI_trait_lightdrinkdesc"] = "不太习惯喝酒, 很容易醉.<br>长时间不喝酒, 或失去“酒鬼”特质后, 会获得此特质.<br>如果再次习惯经常饮酒, 则会失去此特质.",
        ["UI_trait_lighteaterdesc"] = "需要进食的频率更低.",
        ["UI_trait_marksman"] = "持枪执照",
        ["UI_trait_marksmandesc"] = "显然, 你拥有一张持枪执照.",
        ["UI_trait_nightowldesc"] = "睡眠需求很少.<br>即使在休息时也能保持警觉.",
        ["UI_trait_nutritionist"] = "营养师 (动态)",
        ["UI_trait_nutritionist2desc"] = "能查看所有食物的营养价值.",
        ["UI_trait_nutritionistdesc"] = "可以查看所有食物的营养数值.<br>当烹饪技能达到 7 级时, 会自动获得营养师特质.<br>开局携带一根麦片能量棒.",
        ["UI_trait_obese"] = "肥胖 (动态)",
        ["UI_trait_obesedesc"] = "奔跑速度降低, 体力非常差, 更容易受伤.",
        ["UI_trait_outdoorsman"] = "户外达人 (动态)",
        ["UI_trait_outdoorsmandesc"] = "受恶劣天气条件影响较小. <br>如果玩家在户外度过10,000小时, 且没有开阔恐惧, 会自动获得此特质. <br>你开局带有一个睡袋.",
        ["UI_trait_outofshape"] = "体型走样 (动态)",
        ["UI_trait_outofshapedesc"] = "耐力较低, 体力恢复速度更慢.<br>普通人的体能水平对应体能等级 5.<br>当你的体能略低于平均水平时会获得此特质.",
        ["UI_trait_overweight"] = "超重 (动态)",
        ["UI_trait_overweightdesc"] = "奔跑速度降低, 耐力较差, 更容易受伤.",
        ["UI_trait_partyanimal"] = "派对狂人 (动态)",
        ["UI_trait_partyanimaldesc"] = "派对灵魂人物和天才<SPACE><RGB:1,0.8,0>舞者<RGB:1,1,1><SPACE> 随时准备嗨翻舞池保持能量.",
        ["UI_trait_patientdesc"] = "不太容易生气.",
        ["UI_trait_pronetoillness"] = "多病体质",
        ["UI_trait_pronetoillnessdesc"] = "更容易生病. <br>丧尸化速度更快. <br>初始携带抗生素.",
        ["UI_trait_resilientdesc"] = "不太容易生病. <br>丧尸化速度更慢.",
        ["UI_trait_shortsigh"] = "近视",
        ["UI_trait_shortsighdesc"] = "视野距离缩短. <br>视野消散速度减慢. <br>瞄准效果下降.",
        ["UI_trait_shorttemper"] = "脾气暴躁",
        ["UI_trait_shorttemperdesc"] = "非常容易发火.",
        ["UI_trait_sloppy"] = "邋遢鬼 (动态)",
        ["UI_trait_sloppydesc"] = "整洁从来不是你的优先事项. <br>对肮脏环境有很高的容忍度. <br>讨厌<SPACE><RGB:1,0.8,0>清洁<RGB:1,1,1><SPACE>且清洁花费时间更长. <br>几乎从不记得冲厕所. <br>更容易把马桶堵住. <br>工作时更容易产生垃圾, 没洗干净时也更容易弄得满是血迹和污垢.",
        ["UI_trait_stout"] = "壮实 (动态)",
        ["UI_trait_stoutdesc"] = "近战武器的击退效果提高. <br>负重能力提升. <br>普通人的力量水平大致对应力量等级5. <br>当力量达到6级时会获得此特质.",
        ["UI_trait_strong"] = "强壮 (动态)",
        ["UI_trait_strongdesc"] = "近战武器的击退效果大幅提高. <br>负重能力显著提升. <br>普通人的力量水平大致对应力量等级5. <br>当力量达到8级时会获得此特质.",
        ["UI_trait_thickskinned"] = "皮糙肉厚 (动态)",
        ["UI_trait_thickskinneddesc"] = "更不容易被抓伤或咬伤. <br>在承受大量伤害后会获得此特质.",
        ["UI_trait_tidy"] = "整洁 (动态)",
        ["UI_trait_tidydesc"] = "保持空间整洁对你来说是顺其自然的事. <br>工作时产生垃圾的概率更低, 未清洗时产生血迹/污垢的概率也更低. <br>热爱<SPACE><RGB:1,0.8,0>清洁<RGB:1,1,1><SPACE>且清洁速度更快.",
        ["UI_trait_tonedeaf"] = "音痴 (动态)",
        ["UI_trait_tonedeafdesc"] = "音痴缺乏良好的音乐听觉. <br>难以分辨音符和节奏, 演奏旋律可能有困难. <br>可以说这并不是他们首选的娱乐方式. <br>讨厌演奏乐器, 被迫演奏会变得不快乐. <br>演奏时学习速度更慢, 且更容易犯错.",
        ["UI_trait_underweight"] = "体重不足 (动态)",
        ["UI_trait_underweightdesc"] = "力量偏低, 耐力不足, 更容易受伤.",
        ["UI_trait_unfit"] = "体弱 (动态)",
        ["UI_trait_unfitdesc"] = "耐力极低, 体力恢复速度非常缓慢. 普通人的体能水平大致对应体能等级5. <br>当你的体能远低于平均水平时会获得此特质.",
        ["UI_trait_unluckydesc"] = "凡是可能出错的事, 往往都会出错.",
        ["UI_trait_veryunderweight"] = "严重体重不足 (动态)",
        ["UI_trait_veryunderweightdesc"] = "力量极低, 耐力极差, 更容易受伤.",
        ["UI_trait_virtuoso"] = "音乐家 (动态)",
        ["UI_trait_virtuosodesc"] = "天生的音乐家, 拥有演奏和作曲的天赋. <br>对节奏旋律有与生俱来的理解力, 能轻松即兴创作或适应不同音乐风格. <br>同时也是富有魅力的表演者, 能用音乐和台风征服观众. <br>学习音乐速度远超常人, 演奏乐器时最快乐.",
        ["UI_trait_weak"] = "虚弱 (动态)",
        ["UI_trait_weakdesc"] = "近战武器几乎没有击退效果. <br>负重能力极低. <br>当你的力量远低于平均水平时会获得此特质.",
        ["UI_trait_weightgaindesc"] = "体质长期偏向于发胖. <br>初始自带“超重”特质.",
        ["UI_trait_weightlossdesc"] = "体质长期偏向于消瘦. <br>初始自带“体重不足”特质.",
    },
